const clone = <T,>(value:T):T => structuredClone(value)
const words = (value:string) => value.replace(/_/g, " ")
const dispositions:Record<M71Disposition,string> = {unassessed:"Not assessed",missing:"Missing",included_activity:"Proposed inclusion",included_estimate:"Estimate proposed",excluded:"Proposed exclusion",not_applicable:"Proposed not applicable"}
const domainName = (domain:string) => domain.startsWith("scope3_") ? `${domain.slice(7)}. ${M71_CATEGORIES[Number(domain.slice(7))-1]}` : ({stationary_combustion:"Stationary combustion",mobile_combustion:"Mobile combustion",process:"Process emissions",fugitive:"Fugitive emissions",electricity:"Purchased electricity",steam:"Purchased steam",heat:"Purchased heat",cooling:"Purchased cooling",location_based:"Location-based Scope 2 view",market_based:"Market-based Scope 2 view"}[domain]??words(domain))
const limits = ["Fictional data only", "Corporate inventory remains incomplete", "Methods are not released", "Reporting requirements are not determined", "No emissions totals are calculated", "No external assurance"]

function findingLabel(snapshot:M71Snapshot,id:string|null):string {
 if(!id)return "Company register"
 const entity=snapshot.entities.find(e=>e.id===id);if(entity)return entity.legalName
 const facility=snapshot.facilities.find(f=>f.id===id);if(facility)return facility.name
 const source=snapshot.sources.find(r=>r.id===id);if(source)return `${source.name} · ${snapshot.facilities.find(f=>f.id===source.facilityId)?.name??snapshot.entities.find(e=>e.id===source.entityId)?.legalName??"Operation"}`
 const decision=snapshot.boundaryDecisions.find(r=>r.id===id);if(decision)return `${snapshot.entities.find(e=>e.id===decision.entityId)?.legalName??"Entity"} boundary`
 const relationship=snapshot.relationships.find(r=>r.id===id);if(relationship)return `${snapshot.entities.find(e=>e.id===relationship.childEntityId)?.legalName??"Entity"} ownership and control`
 const row=snapshot.coverageItems.find(r=>r.id===id);if(row)return `${domainName(row.domain)}${row.sourceId?` · ${findingLabel(snapshot,row.sourceId)}`:" · Company-wide screening"}`
 return "Reporting requirement"
}

