 for(const e of s.entities){m71Keys(e,["id","legalName","countryCode","regionCode","start","endExclusive","evidenceRefs"]);e.legalName=label(e.legalName,160);if(typeof e.countryCode!=="string"||!/^[A-Z]{2}$/.test(e.countryCode)||!(e.regionCode===null||typeof e.regionCode==="string"&&/^[A-Z0-9-]{1,12}$/.test(e.regionCode)))fail();interval(e);e.evidenceRefs=refs(e.evidenceRefs)}
