}
export function validateM71Save(v:unknown):M71SaveInput{m71Keys(v,["snapshot","expectedVersionId","expectedVersionSha256","correctionReason","idempotencyKey"]);if(!m71Uuid(v.idempotencyKey))fail();if(v.expectedVersionId===null){if(v.expectedVersionSha256!==null||v.correctionReason!==null)fail()}else if(!m71Uuid(v.expectedVersionId)||!m71HashString(v.expectedVersionSha256)||v.correctionReason===null)fail();return {...v,snapshot:validateM71Snapshot(v.snapshot),correctionReason:nullableLabel(v.correctionReason)} as unknown as M71SaveInput}
export function validateM71Review(v:unknown):M71ReviewInput{m71Keys(v,["versionId","expectedVersionSha256","decision","note","acknowledgedLimitations","idempotencyKey"]);if(!m71Uuid(v.versionId)||!m71HashString(v.expectedVersionSha256)||!m71Uuid(v.idempotencyKey))fail();enumeration(v.decision,["accepted_bounded_internal","changes_requested"]);const note=label(v.note);if(m71CanonicalJson(v.acknowledgedLimitations)!==m71CanonicalJson(M71_LIMITATIONS))fail("Acknowledge the exact synthetic limitations.");return {...v,note} as unknown as M71ReviewInput}
export function deriveM71Findings(s:M71Snapshot):M71Finding[]{const out:M71Finding[]=[];const add=(code:string,recordId:string|null,message:string)=>out.push({code,recordId,message});add("requirements_not_determined",null,"Corporate applicability and reporting requirements remain undetermined.");add("methods_not_released",null,"No corporate calculation method is released; emissions remain unknown.");if(s.consolidationApproach!=="operational_control")add("unsupported_consolidation",null,"This consolidation approach requires a later reviewed method.");for(const e of [...s.entities,...s.facilities]){if(e.countryCode!=="US"||e.regionCode!=="CA")add("unsupported_geography",e.id,"Discovered operations remain registered; this milestone supports only California operations.");if(e.start!==s.period.start||e.endExclusive!==s.period.endExclusive)add("unsupported_temporal_allocation",e.id,"Partial-year control/operations need reviewed interval allocation.")}
 for(const r of s.relationships){if(r.start!==s.period.start||r.endExclusive!==s.period.endExclusive||r.ownershipPercent!=="100")add("unsupported_boundary_relationship",r.id,"Partial-year or non-wholly-owned relationships need reviewed allocation.");if(!r.controlFacts||!r.evidenceRefs.length)add("control_evidence_missing",r.id,"Control facts and supporting evidence are incomplete.")}
 for(const b of s.boundaryDecisions){if(["missing","unassessed"].includes(b.disposition))add("boundary_unreconciled",b.id,"Expected entity remains unreconciled.");if(["excluded","not_applicable"].includes(b.disposition))add(b.reason&&b.evidenceRefs.length?"boundary_assertion_unverified":"boundary_basis_missing",b.id,"Boundary exclusion/non-applicability remains visible and requires qualified review.")}
