export function parseM71Json(text:string,maxBytes=250000):unknown{if(!Number.isInteger(maxBytes)||maxBytes<1||maxBytes>4000000||new TextEncoder().encode(text).length>maxBytes)fail("Coverage request is too large.");let i=0;const ws=()=>{while(/\s/.test(text[i]??"")&&i<text.length)i++};const str=()=>{const start=i++;while(i<text.length){if(text[i]==="\\"){i+=2;continue}if(text[i++]==='"')return JSON.parse(text.slice(start,i)) as string}return fail()};const scan=()=>{ws();if(text[i]==="{"){i++;const keys=new Set<string>();ws();if(text[i]==="}"){i++;return}while(i<text.length){ws();if(text[i]!=='"')fail();const key=str();if(keys.has(key))fail("Duplicate JSON keys are not accepted.");keys.add(key);ws();if(text[i++]!==":")fail();scan();ws();const end=text[i++];if(end==="}")return;if(end!==",")fail()}}else if(text[i]==="["){i++;ws();if(text[i]==="]"){i++;return}while(i<text.length){scan();ws();const end=text[i++];if(end==="]")return;if(end!==",")fail()}}else if(text[i]==='"'){str()}else{const start=i;while(i<text.length&&!/[\s,}\]]/.test(text[i]!))i++;if(start===i)fail();JSON.parse(text.slice(start,i))}};try{scan();ws();if(i!==text.length)fail();return JSON.parse(text)}catch(e){if(e instanceof M71ValidationError)throw e;return fail()}}

import type { WorkspaceSql } from "./workspace"
import { M71_PROFILE, M71_LIMITATIONS, M71_ARTIFACT, type M71Register, type M71Version, type M71Review } from "./m71-contract"
import { M71_EVIDENCE_SHA256, validateM71Snapshot, validateM71Review, m71CanonicalJson, m71VersionHashPayload, m71ReviewHashPayload, deriveM71Findings, m71Uuid, m71Keys } from "./m71-validation"
export * from "./m71-contract"
