  const audit=all.audits.filter(a=>a.record_id===v.id&&a.kind==="save");if(audit.length!==1||audit[0]!.record_sha256!==v.versionSha256||audit[0]!.actor_id!==v.createdBy||iso(audit[0]!.created_at)!==v.createdAt)return fail()
